from azure.storage.blob import BlobServiceClient, BlobClient, ContainerClient

class StorageClient:
    def __init__(self, connection_string):
        self.blob_service_client = BlobServiceClient.from_connection_string(connection_string)

    def get_container_client(self, container_name):
        return self.blob_service_client.get_container_client(container_name)

    def get_blob_client(self, container_name, blob_name):
        return self.blob_service_client.get_blob_client(container_name, blob_name)

from typing import Any, Dict

class StorageRequest:
    def __init__(self, **kwargs: Any):
        self.__dict__.update(kwargs)

class StorageResponse:
    def __init__(self, **kwargs: Any):
        self.__dict__.update(kwargs)

def normalize_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {k: v for k, v in payload.items() if v is not None}

from storage_client import StorageClient

def object_metadata(connection_string: str, container_name: str, blob_name: str):
    client = StorageClient(connection_string)
    blob_client = client.get_blob_client(container_name, blob_name)
    return blob_client.get_blob_properties()

from azure.ai.vision.image_analysis import ImageAnalysisClient
from azure.ai.vision.image_analysis.models import VisualFeatures

class OCRClient:
    def __init__(self, endpoint, key):
        self.client = ImageAnalysisClient(endpoint, key)

    def ocr(self, image_url):
        result = self.client.analyze(image_url, visual_features=[VisualFeatures.TEXT])
        return result.text.text

from azure.ai.translation.document import DocumentTranslationClient

class TranslationClient:
    def __init__(self, endpoint, key):
        self.client = DocumentTranslationClient(endpoint, key)

    def translate(self, source_text, target_language):
        result = self.client.translate(source_text, target_language)
        return result.translations[0].text

from azure.ai.textanalytics import TextAnalyticsClient
from azure.core.credentials import AzureKeyCredential

class SummaryClient:
    def __init__(self, endpoint, key):
        self.client = TextAnalyticsClient(endpoint, AzureKeyCredential(key))

    def summarize(self, text):
        result = self.client.summarize(text)
        return result[0].sentences[0].text

from azure.ai.textanalytics import TextAnalyticsClient
from azure.core.credentials import AzureKeyCredential

class EmbeddingClient:
    def __init__(self, endpoint, key):
        self.client = TextAnalyticsClient(endpoint, AzureKeyCredential(key))

    def embed(self, text):
        result = self.client.extract_key_phrases(text)
        return result.key_phrases
